def predict_v7(grid):
    h, w = len(grid), len(grid[0])
    output = [[(grid[r][c]) if grid[r][c] != 0 else 0 for c in range(w)] for r in range(h)]

    sources = [(r, c, grid[r][c]) for r in range(h) for c in range(w) 
               if grid[r][c] != 0 and grid[r][c] != 3]

    for rs, cs, vs in sources:
        # Up
        for r in range(rs - 3, rs):
            if r >= 0:
                if output[r][cs] == 0:  # Only fill empty cells
                    output[r][cs] = vs
                # Don't overwrite non-zeros (original 3s or other sources)

        # Down
        for r in range(rs + 1, min(rs + 4, h)):
            if output[r][cs] == 0:
                output[r][cs] = vs

        # Left
        for c in range(cs - 3, cs):
            if c >= 0:
                if output[rs][c] == 0:
                    output[rs][c] = vs

        # Right  
        for c in range(cs + 1, min(cs + 4, w)):
            if output[rs][c] == 0:
                output[rs][c] = vs

