    for r, c in [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]:
        output[r][c] = 3

    # Track which surface cells to preserve
    surface_to_preserve = set()

    # Identify extending sources (above barrier, in adjacent columns)
    for barrier_col, (barrier_start, barrier_end) in barriers.items():
        for adj_col in [barrier_col - 1, barrier_col + 1]:
            if 0 <= adj_col < w:
