                for r in range(h):
                    for c in range(w):
                        if adj_col == c and grid[r][c] > 0 and grid[r][c] != 3 and r <= barrier_start:
                            surface_to_preserve.add((r, c))
                            # Fill DOWN from barrier_start
                            for rr in range(barrier_start, barrier_end + 2):  # 5 to 14 inclusive
                                if 0 <= rr < h:
                                    output[rr][adj_col] = grid[r][c]

    # Mark preserving surface cells (but not 3s)
    for r in range(h):
        for c in range(w):
            if (r, c) in surface_to_preserve and grid[r][c] > 0 and grid[r][c] != 3:
                output[r][c] = grid[r][c]

    return output

