       - Source cells of extending sources (sources above barrier in adjacent cols)
    5. Add source cells to preserve at their surface positions
    """
    h, w = len(grid), len(grid[0])

    # Find barriers
    barriers = {}
    barrier_cells = set()
    for c in range(w):
