            barriers[c] = min(rows_with_3), max(rows_with_3)
            barrier_cells.update((r, c) for r in rows_with_3)

    # Track cells to preserve
    to_preserve = barrier_cells.copy()

    # Identify extending sources (above barrier, in adjacent columns)
    for barrier_col, (barrier_start, barrier_end) in barriers.items():
        for adj_col in [barrier_col - 1, barrier_col + 1]:
            if 0 <= adj_col < w:
                # Mark source cells
                for r in range(h):
                    for c in range(w):
                        if adj_col == c and grid[r][c] > 0 and grid[r][c] != 3 and r <= barrier_start:
                            to_preserve.add((r, c))
                            # Fill DOWN from barrier_start to barrier_end + 1
                            for rr in range(barrier_start, barrier_end + 2):  # 5 to 14 inclusive
                                if 0 <= rr < h and 0 <= adj_col < w:
                                    if grid[r][c] != barrier_cells.get((rr, adj_col), -1):  # Don't overwrite barrier
                                        # Use same value for all cells in fill
                                        pass
                                    output[rr][adj_col] = grid[r][c]
    # Initialize output
    output = [[0 for c in range(w)] for r in range(h)]

    for cc in barrier_cells:
        output[cc[0]][cc[1]] = 3

    # Mark preserving source cells and fill
    for barrier_col, (barrier_start, barrier_end) in barriers.items():
        for adj_col in [barrier_col - 1, barrier_col + 1]:
            if 0 <= adj_col < w:
                sources_above = [(r, grid[r][c]) 
                                 for r in range(h) 
                                 for c in range(w)
                                 if adj_col == c and grid[r][c] > 0 and grid[r][c] != 3 and r <= barrier_start]
                # Sort by row (bottom to top)
                sources_above.sort(reverse=True)

                for rs, vs in sources_above:
                    for r in range(barrier_start, barrier_end + 2):  # 5 to 14 inclusive
                        if 0 <= r < h and 0 <= adj_col < w:
